func newJournalEntryLine() unsafe.Pointer { return unsafe.Pointer(new(journalentry.JournalEntryLine)) }

func newNJournalEntryLine(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]journalentry.JournalEntryLine, n)))
}

func ptrJournalEntryLine(p unsafe.Pointer, c int32) any {
	r := (*journalentry.JournalEntryLine)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.JournalEntryID))
	case 4:
		return (*string)(unsafe.Pointer(&r.GLAccountID))
	case 5:
		return &r.LineNumber
	case 6:
		return &r.Description
	case 7:
		return &r.DebitAmount
	case 8:
		return &r.CreditAmount
	case 9:
		return &r.NetAmount
	case 10:
		return (*string)(unsafe.Pointer(&r.DepartmentID))
	case 11:
		return (*string)(unsafe.Pointer(&r.ProjectID))
	case 12:
		return (*string)(unsafe.Pointer(&r.LocationID))
	case 13:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 14:
		return (*string)(unsafe.Pointer(&r.VendorID))
	case 15:
		return &r.TaxCode
	case 16:
		return &r.TaxAmount
	case 17:
		return &r.IsTaxLine
	case 18:
		return &r.IsReconciled
	case 19:
		return &r.ReconciledAt
	case 20:
		return (*string)(unsafe.Pointer(&r.ReconciledByID))
	case 21:
		return &r.Version
	case 22:
		return &r.CreatedAt
	case 23:
		return &r.UpdatedAt
	}
	return nil
}

func valueJournalEntryLine(p unsafe.Pointer, c int32) any {
	r := (*journalentry.JournalEntryLine)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.JournalEntryID)
	case 4:
		return string(r.GLAccountID)
	case 5:
		return r.LineNumber
	case 6:
		return r.Description
	case 7:
		return r.DebitAmount
	case 8:
		return r.CreditAmount
	case 9:
		return r.NetAmount
	case 10:
		if r.DepartmentID == "" {
			return nil
		}
		return string(r.DepartmentID)
	case 11:
		if r.ProjectID == "" {
			return nil
		}
		return string(r.ProjectID)
	case 12:
		if r.LocationID == "" {
			return nil
		}
		return string(r.LocationID)
	case 13:
		if r.CustomerID == "" {
			return nil
		}
		return string(r.CustomerID)
	case 14:
		if r.VendorID == "" {
			return nil
		}
		return string(r.VendorID)
	case 15:
		if r.TaxCode == "" {
			return nil
		}
		return r.TaxCode
	case 16:
		return r.TaxAmount
	case 17:
		return r.IsTaxLine
	case 18:
		return r.IsReconciled
	case 19:
		if r.ReconciledAt == nil {
			return nil
		}
		return *r.ReconciledAt
	case 20:
		if r.ReconciledByID == "" {
			return nil
		}
		return string(r.ReconciledByID)
	case 21:
		return r.Version
	case 22:
		return r.CreatedAt
	case 23:
		return r.UpdatedAt
	}
	return nil
}

func attachJournalEntryLine(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*journalentry.JournalEntryLine)(p)
	switch rel {
	case 0:
		r.JournalEntry = (*journalentry.JournalEntry)(child)
	case 1:
		r.GLAccount = (*glaccount.GLAccount)(child)
	case 2:
		r.Customer = (*customer.Customer)(child)
	case 3:
		r.Location = (*location.Location)(child)
	}
}

func init() {
	journalBatchesTable.Relations[0].Target = fiscalyeardb.FiscalYearsSchema()
	journalBatchesTable.Relations[1].Target = fiscalperioddb.FiscalPeriodsSchema()
	journalBatchesTable.Relations[2].Target = JournalEntriesSchema()
	journalEntriesTable.Relations[0].Target = fiscalyeardb.FiscalYearsSchema()
	journalEntriesTable.Relations[1].Target = fiscalperioddb.FiscalPeriodsSchema()
	journalEntriesTable.Relations[2].Target = JournalBatchesSchema()
	journalEntriesTable.Relations[3].Target = JournalEntriesSchema()
	journalEntriesTable.Relations[4].Target = JournalEntriesSchema()
	journalEntriesTable.Relations[5].Target = JournalEntryLinesSchema()
	journalEntryLinesTable.Relations[0].Target = JournalEntriesSchema()
	journalEntryLinesTable.Relations[1].Target = glaccountdb.GLAccountsSchema()
	journalEntryLinesTable.Relations[2].Target = customerdb.CustomersSchema()
	journalEntryLinesTable.Relations[3].Target = locationdb.LocationsSchema()
}

